# Represents an individual user or assistant message within an AiChatSession.
class AiChatMessage < ApplicationRecord
  ROLES = %w[user assistant].freeze

  belongs_to :ai_chat_session

  validates :role, presence: true, inclusion: { in: ROLES }
  validates :content, presence: true

  # Checks whether the message was sent by the user.
  #
  # @return [Boolean]
  def user?
    role == "user"
  end

  # Checks whether the message was generated by the Gemini assistant.
  #
  # @return [Boolean]
  def assistant?
    role == "assistant"
  end
end
